-- SGQ avançado: riscos, processos, 5W2H, indicadores e Ishikawa
create table if not exists public.erp_qualidade_riscos (id uuid primary key default gen_random_uuid(),empresa_id uuid not null references public.erp_empresas(id),tipo text not null check (tipo in ('PROCESSO','FORNECEDOR','OPORTUNIDADE')),processo_id uuid,fornecedor_id uuid references public.erp_fornecedores(id),titulo text not null,causa text,consequencia text,severidade integer not null default 1 check (severidade between 1 and 10),ocorrencia integer not null default 1 check (ocorrencia between 1 and 10),deteccao integer not null default 1 check (deteccao between 1 and 10),score integer generated always as (severidade*ocorrencia*deteccao) stored,resposta text,responsavel_id uuid references public.erp_usuarios(id),prazo date,status text not null default 'aberto',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.erp_qualidade_processos (id uuid primary key default gen_random_uuid(),empresa_id uuid not null references public.erp_empresas(id),codigo text not null,nome text not null,objetivo text,entradas text,fornecedores text,atividades text,saidas text,clientes text,recursos text,indicadores text,riscos text,documentos text,responsavel_id uuid references public.erp_usuarios(id),status text not null default 'ativo',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(empresa_id,codigo));
create table if not exists public.erp_qualidade_acoes (id uuid primary key default gen_random_uuid(),empresa_id uuid not null references public.erp_empresas(id),origem_tipo text not null default 'RPNC',origem_id uuid,what text not null,why text,where_to text,when_date date,who_id uuid references public.erp_usuarios(id),how text,how_much numeric default 0,status text not null default 'aberta',eficacia text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.erp_qualidade_indicadores (id uuid primary key default gen_random_uuid(),empresa_id uuid not null references public.erp_empresas(id),codigo text not null,nome text not null,unidade text,meta numeric,valor_atual numeric,periodo text,responsavel_id uuid references public.erp_usuarios(id),status text not null default 'ativo',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(empresa_id,codigo));
create table if not exists public.erp_qualidade_ishikawa (id uuid primary key default gen_random_uuid(),empresa_id uuid not null references public.erp_empresas(id),rpnc_id uuid references public.erp_rpnc(id),efeito text not null,maquina text,metodo text,mao_de_obra text,material text,medicao text,meio_ambiente text,cinco_porques text,created_at timestamptz not null default now());
alter table public.erp_qualidade_riscos enable row level security;
alter table public.erp_qualidade_processos enable row level security;
alter table public.erp_qualidade_acoes enable row level security;
alter table public.erp_qualidade_indicadores enable row level security;
alter table public.erp_qualidade_ishikawa enable row level security;
drop policy if exists erp_qualidade_riscos_tenant on public.erp_qualidade_riscos;
drop policy if exists erp_qualidade_processos_tenant on public.erp_qualidade_processos;
drop policy if exists erp_qualidade_acoes_tenant on public.erp_qualidade_acoes;
drop policy if exists erp_qualidade_indicadores_tenant on public.erp_qualidade_indicadores;
drop policy if exists erp_qualidade_ishikawa_tenant on public.erp_qualidade_ishikawa;
create policy erp_qualidade_riscos_tenant on public.erp_qualidade_riscos for all to authenticated using (empresa_id=public.erp_current_empresa_id()) with check (empresa_id=public.erp_current_empresa_id());
create policy erp_qualidade_processos_tenant on public.erp_qualidade_processos for all to authenticated using (empresa_id=public.erp_current_empresa_id()) with check (empresa_id=public.erp_current_empresa_id());
create policy erp_qualidade_acoes_tenant on public.erp_qualidade_acoes for all to authenticated using (empresa_id=public.erp_current_empresa_id()) with check (empresa_id=public.erp_current_empresa_id());
create policy erp_qualidade_indicadores_tenant on public.erp_qualidade_indicadores for all to authenticated using (empresa_id=public.erp_current_empresa_id()) with check (empresa_id=public.erp_current_empresa_id());
create policy erp_qualidade_ishikawa_tenant on public.erp_qualidade_ishikawa for all to authenticated using (empresa_id=public.erp_current_empresa_id()) with check (empresa_id=public.erp_current_empresa_id());
create index if not exists idx_erp_qualidade_riscos_empresa_tipo on public.erp_qualidade_riscos(empresa_id,tipo,status);
create index if not exists idx_erp_qualidade_acoes_empresa_status on public.erp_qualidade_acoes(empresa_id,status);
create index if not exists idx_erp_qualidade_ishikawa_empresa_rpnc on public.erp_qualidade_ishikawa(empresa_id,rpnc_id);
